export const BENGALI_DIGITS = ['০','১','২','৩','৪','৫','৬','৭','৮','৯'];

export function toBengaliNum(n: number): string {
  return String(n).split('').map(d => BENGALI_DIGITS[parseInt(d)]).join('');
}

export interface Chapter {
  num: number;
  bengaliNum: string;
  ordinal: string;
  name: string;
  verses: number;
}

export interface VerseContent {
  speaker?: string;
  sanskrit: string;
  bengali: string;
}

const ORDINALS: Record<number, string> = {
  1:'১ম', 2:'২য়', 3:'৩য়', 4:'৪র্থ', 5:'৫ম',
  6:'৬ষ্ঠ', 7:'৭ম', 8:'৮ম', 9:'৯ম', 10:'১০ম',
  11:'১১তম', 12:'১২তম', 13:'১৩তম', 14:'১৪তম', 15:'১৫তম',
  16:'১৬তম', 17:'১৭তম', 18:'১৮তম',
};

