export function getVerseContent(chapterNum: number, verseNum: number): VerseContent {
  if (chapterNum === 1) {
    const v = CH1[verseNum];
    if (v) return v;
  }
  if (chapterNum === 2) {
    const v = CH2[verseNum];
    if (v) return v;
  }
  if (chapterNum === 3) {
    const v = CH3[verseNum];
    if (v) return v;
  }
  if (chapterNum === 4) {
    const v = CH4[verseNum];
    if (v) return v;
  }
  if (chapterNum === 5) {
    const v = CH5[verseNum];
    if (v) return v;
  }
  if (chapterNum === 6) {
    const v = CH6[verseNum];
    if (v) return v;
  }
  if (chapterNum === 7) {
    const v = CH7[verseNum];
    if (v) return v;
  }
  if (chapterNum === 8) {
    const v = CH8[verseNum];
    if (v) return v;
  }
  if (chapterNum === 9) {
    const v = CH9[verseNum];
    if (v) return v;
  }
  if (chapterNum === 10) {
    const v = CH10[verseNum];
    if (v) return v;
  }
  if (chapterNum === 11) {
    const v = CH11[verseNum];
    if (v) return v;
  }
  if (chapterNum === 12) {
    const v = CH12[verseNum];
    if (v) return v;
  }
  if (chapterNum === 13) {
    const v = CH13[verseNum];
    if (v) return v;
  }
  if (chapterNum === 14) {
    const v = CH14[verseNum];
    if (v) return v;
  }
  if (chapterNum === 15) {
    const v = CH15[verseNum];
    if (v) return v;
  }
  if (chapterNum === 16) {
    const v = CH16[verseNum];
    if (v) return v;
  }
  if (chapterNum === 17) {
    const v = CH17[verseNum];
    if (v) return v;
  }
  if (chapterNum === 18) {
    const v = CH18[verseNum];
    if (v) return v;
  }
  return {
    sanskrit: `[অধ্যায় ${toBengaliNum(chapterNum)}, শ্লোক ${toBengaliNum(verseNum)}] — সংস্কৃত শ্লোকের পাঠ শীঘ্রই যোগ করা হবে।`,
    bengali:  `[বাংলা অনুবাদ] — এই শ্লোকের বাংলা অনুবাদ ও ভাষ্য শীঘ্রই যোগ করা হবে।`,
  };
}
